(() => {
  const DAY = 864e5;
  const ALLOWED = new Set(["bookedAt", "transitDays", "holidays"]);
  const parse = (d) => {
    const [y, m, dd] = String(d).split("-").map(Number);
    return Date.UTC(y, m - 1, dd);
  };
  const fmt = (t) => new Date(t).toISOString().slice(0, 10);
  const toSet = (h) => h instanceof Set ? h : new Set(h || []);
  function isBusinessDay(date, holidays) {
    const wd = new Date(parse(date)).getUTCDay();
    return wd >= 1 && wd <= 5 && !toSet(holidays).has(date);
  }
  function nextBusinessDay(date, holidays) {
    const set = toSet(holidays);
    let t = parse(date);
    let d;
    do {
      t += DAY;
      d = fmt(t);
    } while (!isBusinessDay(d, set));
    return d;
  }
  function promiseDelivery(input) {
    for (const key of Object.keys(input)) {
      if (!ALLOWED.has(key)) throw new Error("unknown field: " + key);
    }
    const { bookedAt, transitDays, holidays } = input;
    if (!Number.isInteger(transitDays) || transitDays < 0) throw new Error("invalid transitDays");
    const set = toSet(holidays);
    const [date, time] = String(bookedAt).split("T");
    const hhmm = (time || "").slice(0, 5);
    const shipDate = isBusinessDay(date, set) && hhmm < "14:00" ? date : nextBusinessDay(date, set);
    let deliveryDate = shipDate;
    for (let i = 0; i < transitDays; i++) deliveryDate = nextBusinessDay(deliveryDate, set);
    return { shipDate, deliveryDate };
  }
  return { promiseDelivery, isBusinessDay };
})()

