build.unitScript:
test("AC-1: Friday 15:00 booking with Monday holiday ships Tuesday and delivers Thursday", () => {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 2, holidays: ["2026-07-06"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-09" });
});
test("AC-2: Wednesday 09:00 booking with 1 transit day ships same day and delivers Thursday", () => {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: ["2026-07-06"] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-02" });
});
test("AC-3: booking at exactly 14:00 ships next business day", () => {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T14:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-02", deliveryDate: "2026-07-03" });
});
test("booking at 13:59 ships same day and zero transit days delivers on ship date", () => {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T13:59", transitDays: 0, holidays: [] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-01" });
});
test("rejects negative or fractional transit days and unknown input fields", () => {
  assert.throws(() => code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: -1, holidays: [] }), /^Error: invalid transitDays$/);
  assert.throws(() => code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1.5, holidays: [] }), /^Error: invalid transitDays$/);
  assert.throws(() => code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [], extra: 1 }), /^Error: unknown field: extra$/);
});
test("isBusinessDay is false on weekends and listed holidays and true on other weekdays", () => {
  assert.equal(code.isBusinessDay("2026-07-04", []), false);
  assert.equal(code.isBusinessDay("2026-07-05", []), false);
  assert.equal(code.isBusinessDay("2026-07-06", ["2026-07-06"]), false);
  assert.equal(code.isBusinessDay("2026-07-06", []), true);
  assert.equal(code.isBusinessDay("2026-07-07", ["2026-07-06"]), true);
});

build.testScript:
test("after Friday cutoff skips the weekend and Monday holiday then counts two transit days", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 2, holidays: ["2026-07-06"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-09" });
});
test("before cutoff on Wednesday ships that day and delivers the next business day", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-02" });
});
test("booking at exactly 14:00 is not before the cutoff and ships the next business day", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T14:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-02", deliveryDate: "2026-07-03" });
});
test("booking at 13:59 is before the cutoff and ships the same business day", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T13:59", transitDays: 1, holidays: [] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-02" });
});
test("booking at 14:01 is after the cutoff and ships the next business day", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T14:01", transitDays: 1, holidays: [] }), { shipDate: "2026-07-02", deliveryDate: "2026-07-03" });
});
test("Saturday booking with zero transit days ships and delivers on the next Monday", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-04T09:00", transitDays: 0, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-06" });
});
test("Saturday booking at 14:00 ships the next Monday and delivers Tuesday", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-04T14:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-07" });
});
test("Sunday morning booking is not a ship day and ships Monday then delivers Tuesday", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-05T09:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-07" });
});
test("a holiday listed first is not a ship day", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-06T09:00", transitDays: 1, holidays: ["2026-07-06", "2026-01-01", "2026-12-25"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-08" });
});
test("a holiday listed in the middle is not a ship day", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-06T09:00", transitDays: 1, holidays: ["2026-01-01", "2026-07-06", "2026-12-25"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-08" });
});
test("a holiday listed last is not a ship day", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-06T09:00", transitDays: 1, holidays: ["2026-01-01", "2026-12-25", "2026-07-06"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-08" });
});
test("delivery skips a January holiday and weekend after a December ship day", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-12-31T09:00", transitDays: 1, holidays: ["2027-01-01"] }), { shipDate: "2026-12-31", deliveryDate: "2027-01-04" });
});
test("leap day before cutoff ships that day and two transit days land on the following Monday", function() {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2024-02-29T09:00", transitDays: 2, holidays: [] }), { shipDate: "2024-02-29", deliveryDate: "2024-03-04" });
});
test("negative transit days throws invalid transitDays", function() {
  assert.throws(function() {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: -1, holidays: [] });
  }, /^invalid transitDays$/);
});
test("a transit day count that is not a whole number throws invalid transitDays", function() {
  assert.throws(function() {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1.5, holidays: [] });
  }, /^invalid transitDays$/);
});
test("an extra input field throws unknown field foo", function() {
  assert.throws(function() {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [], foo: 1 });
  }, /^unknown field: foo$/);
});

